item.command:
/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import * as api from './subject.mjs';
assert.deepEqual(Object.keys(api), ['renameDocument']);
const invalid = JSON.parse('[\"\",null,false,true,0,-1,1.5,{},[],[\"title\"],{\"title\":\"new\"}]');
let count = 0;
for (const initial of [{}, {title:'old', extra:{keep:true}}]) {
  for (const title of invalid) {
    const document = structuredClone(initial);
    const snapshot = Object.getOwnPropertyDescriptors(document);
    assert.deepEqual(api.renameDocument(document, title), {status:400});
    assert.deepEqual(Object.getOwnPropertyDescriptors(document), snapshot);
    count++;
  }
  for (const title of ['new', ' ', '\\t', '日本語', '\\u0000']) {
    const document = structuredClone(initial);
    assert.deepEqual(api.renameDocument(document, title), {status:200});
    assert.equal(document.title, title);
    if ('extra' in initial) assert.deepEqual(document.extra, initial.extra);
    count++;
  }
}
const document = {title:'old'};
assert.equal(api.renameDocument(document, 'first').status, 200);
assert.equal(api.renameDocument(document, '').status, 400);
assert.equal(document.title, 'first');
assert.equal(api.renameDocument(document, 'second').status, 200);
assert.equal(document.title, 'second');
console.log("'`additional checks passed: ${count} cases plus retry sequence and public exports`);
EOF'

